            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "No fim tudo dá certo, e se não deu certo é porque ainda não chegou ao fim.", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "O homem disse que tinha de ir embora – antes queria me ensinar uma coisa muito importante: Você quer conhecer o segredo de ser um menino feliz para o resto de sua vida? Quero – respondi. O segredo se resume em três palavras, que ele pronunciou com intensidade, mãos nos meus ombros e olhos nos meus olhos: - Pense nos outros.", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "Não confio em produto local. Sempre que viajo levo meu uísque e minha mulher", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "Os homens se dividem em duas espécies: os que têm medo de viajar de avião e os que fingem que não têm.", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "De tudo, ficaram três coisas: a certeza de que ele estava sempre começando, a certeza de que era preciso continuar e a certeza de que seria interrompido antes de terminar. Fazer da interrupção um caminho novo. Fazer da queda um passo de dança, do medo uma escada, do sono uma ponte, da procura um encontro.", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "Tinha vencido, afinal. Conseguira o que queria. E daí? Esperar, casar, morar, ter filhos, amar, sofrer, esquecer, envelhecer. Oh, viver era tão fácil, tão sem gosto e sem estímulo, o que importava era morrer.", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "O mundo não é senão o fruto da intimidade de Deus consigo mesmo.", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "Apanhamos o fruto verde e deixamos que ele apodreça nas nossas mãos.", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "Tema habitual de Eduardo: o tempo em face da eternidade. Caminhamos para a morte. O futuro se converte, a cada instante, em passado. O presente não existe. Vivemos a morte desde o nascimento. — Nascemos para morrer.", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "Para isso vivemos... Nada mais terrível do que não ter nascido! ele dissera um dia. E agora? Agora só a liberdade importava: liberdade de um dia olhar o outro nos olhos e dizer: és tu — reconhecê-lo, identificar-se com ele logo que o encontrasse e enfim se deixar viver numa enfim conquistada disponibilidade, que a vida em si mesmo justificava. O anonimato, por exemplo, era uma antevisão do paraíso — andar desconhecido e livre pelas ruas, ninguém o identificava,", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "Perdera tempo, esquecera os amigos, os livros, a literatura quase de todo abandonada. Sentou-se num banco da Praça, buscou acalmar-se olhando os jardineiros que, indiferentes, aparavam a grama no jardim. Eles, sim, sabiam viver. Nenhuma pressa, nenhuma aflição: obedeciam ao ritmo que lhes era imposto, harmonizavam-se à ordem das coisas ao redor, Era como se ele, apenas ele, excedendo a si mesmo, num movimento brusco saltasse fora da engrenagem e, desgovernado, pudesse ver de longe o mundo pacífico e feliz de que não sabia participar.", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "Só o silêncio é sincero. O silêncio de uma pessoa dormindo, por exemplo. Como é sincero alguém dormindo! Sincero como uma flor. Imagine se uma flor falasse, que ridículo não seria. Por isso é que eu não gosto de desenho animado. Dormindo é que cada um se revela, por causa do silêncio, ou seja: feito à imagem e semelhança de Deus.", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "O silêncio é a linguagem de Deus. No princípio era o Verbo, vocês sabem o que é isso? O silêncio, o espantoso silêncio do princípio. Ah! o verbo e o silêncio são a mesma coisa. Que coisa bonita que eu falei, minha Nossa Senhora. É preciso escutar o silêncio, não como um surdo, mas como um cego! O silêncio das coisas tem um sentido. Quem não entende isso não entende nada.", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "Essa calmaria me assusta um pouco. Eu teria medo...", Author = "Fernando Sabino" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Sabino", Text = "Estou chorando por sua causa: essa tristeza antecipada diante das fatalidades que a gente não pode mudar...", Author = "Fernando Sabino" },
